<script lang="ts" setup>
import type { VxeTableGridOptions } from '#/adapter/vxe-table'; import type { MallEnterpriseApi } from '#/api/mall/product/enterprise'; import { Page,useVbenModal } from '@vben/common-ui'; import { ElMessage } from 'element-plus'; import { ACTION_ICON,TableAction,useVbenVxeGrid } from '#/adapter/vxe-table'; import { auditEnterprise,deleteEnterprise,getEnterprisePage } from '#/api/mall/product/enterprise'; import { $t } from '#/locales'; import { useGridColumns,useGridFormSchema } from './data'; import Form from './modules/form.vue';
const [FormModal,formModalApi]=useVbenModal({connectedComponent:Form,destroyOnClose:true}); function refresh(){gridApi.query()} function create(){formModalApi.setData(null).open()} function edit(row:MallEnterpriseApi.Enterprise){formModalApi.setData(row).open()} async function audit(row:MallEnterpriseApi.Enterprise,status:number){await auditEnterprise(row.id!,status,status===1?'审核通过':'资料不完整，请补充后重新提交');ElMessage.success('操作成功');refresh()} async function del(row:MallEnterpriseApi.Enterprise){try{await deleteEnterprise(row.id!);ElMessage.success($t('ui.actionMessage.deleteSuccess',[row.name]));refresh()}catch{ElMessage.error('删除失败，请稍后重试')}}
const [Grid,gridApi]=useVbenVxeGrid({formOptions:{schema:useGridFormSchema()},gridOptions:{columns:useGridColumns(),height:'auto',keepSource:true,proxyConfig:{ajax:{query:async({page},values)=>getEnterprisePage({pageNo:page.currentPage,pageSize:page.pageSize,...values})}},rowConfig:{keyField:'id',isHover:true},toolbarConfig:{refresh:true,search:true}} as VxeTableGridOptions<MallEnterpriseApi.Enterprise>});
</script>
<template><Page auto-content-height><FormModal @success="refresh"/><Grid table-title="企业入驻审核"><template #toolbar-tools><TableAction :actions="[{label:$t('ui.actionTitle.create',['企业档案']),type:'primary',icon:ACTION_ICON.ADD,auth:['product:enterprise:create'],onClick:create}]"/></template><template #actions="{row}"><TableAction :actions="[{label:$t('common.edit'),type:'link',icon:ACTION_ICON.EDIT,auth:['product:enterprise:update'],onClick:edit.bind(null,row)},{label:'通过',type:'link',auth:['product:enterprise:audit'],ifShow:()=>row.auditStatus===0,onClick:audit.bind(null,row,1)},{label:'驳回',type:'link',danger:true,auth:['product:enterprise:audit'],ifShow:()=>row.auditStatus===0,onClick:audit.bind(null,row,2)},{label:$t('common.delete'),type:'link',danger:true,icon:ACTION_ICON.DELETE,auth:['product:enterprise:delete'],popConfirm:{title:$t('ui.actionMessage.deleteConfirm',[row.name]),confirm:del.bind(null,row)}}]"/></template></Grid></Page></template>
